import type { Resource } from "@/lib/types";

/**
 * Fifth pass (2026-10-29): fight animation and short clips to practise on —
 * punches, kicks, combos, falls, choreography and previs, fight animations
 * made in 2D, Blender, Maya and Roblox, combat game reels, official anime
 * fight clips and lessons on hit timing. Every YouTube video was opened on its
 * own watch page (title, channel, date, length and views are in
 * lib/data/youtube-snapshot.ts); Sakugabooru cuts were found through
 * AnimationReference.org's combat section and the "fighting" tag, with credits
 * from the post's artist tags and the length from the video file. Skipped:
 * re-uploads of other people's footage (stock-clip channels, reel aggregators),
 * game-footage compilations and anything that needed a sign-in to watch.
 */
const fifth = { kind: "reference" as const, addedAt: ADDED_5 };
